using namespace std;

int main() {
    int n;
    string a;
    cin >> n >> a;
    vector<int> cnt(10, 0);
    for (char c : a) {
        int d = c - '0';
        if (d >= 2) cnt[d]++;
    }
    // Decompose digits into primes
    // 4 = 2^2, 6 = 2*3, 8 = 2^3, 9 = 3^2
    // Process 9,8,6,4 first
    cnt[7] += cnt[9]; cnt[3] += 2 * cnt[9]; cnt[9] = 0;
    cnt[7] += cnt[8]; cnt[2] += 3 * cnt[8]; cnt[8] = 0;
    cnt[3] += cnt[6]; cnt[2] += cnt[6]; cnt[6] = 0;
    cnt[2] += 2 * cnt[4]; cnt[4] = 0;
    // Now collect remaining primes: 2,3,5,7
    string res = "";
    for (int d = 7; d >= 2; d--) {
        while (cnt[d] > 0) {
            res += ('0' + d);
            cnt[d]--;
        }
    }
    cout << res << endl;
    return 0;
}
