    // 5 -> 5
    // 6 -> 5,3
    // 7 -> 7
    // 8 -> 7,2,2,2
    // 9 -> 7,3,3
    vector<int> primes;
    for (int i = 0; i < n; i++) {
        int d = a[i] - '0';
        if (d == 0 || d == 1) continue;
        if (d == 2) primes.push_back(2);
        else if (d == 3) primes.push_back(3);
        else if (d == 4) { primes.push_back(3); primes.push_back(2); primes.push_back(2); }
        else if (d == 5) primes.push_back(5);
        else if (d == 6) { primes.push_back(5); primes.push_back(3); }
        else if (d == 7) primes.push_back(7);
        else if (d == 8) { primes.push_back(7); primes.push_back(2); primes.push_back(2); primes.push_back(2); }
        else if (d == 9) { primes.push_back(7); primes.push_back(3); primes.push_back(3); }
    }
    // Count primes
    vector<int> pcnt(10, 0);
    for (int p : primes) pcnt[p]++;
    // Build digits from primes
    // 9 requires 7,3,3
    // 8 requires 7,2,2,2
    // 7 requires 7
    // 6 requires 5,3
    // 5 requires 5
    // 4 requires 3,2,2
    // 3 requires 3
    // 2 requires 2
    string res = "";
    // Process from largest digit to smallest
    while (pcnt[7] > 0 && pcnt[3] >= 2) {
        res += '9';
        pcnt[7]--;
        pcnt[3] -= 2;
    }
    while (pcnt[7] > 0 && pcnt[2] >= 3) {
        res += '8';
        pcnt[7]--;
        pcnt[2] -= 3;
    }
    while (pcnt[7] > 0) {
        res += '7';
        pcnt[7]--;
    }
    while (pcnt[5] > 0 && pcnt[3] > 0) {
        res += '6';
        pcnt[5]--;
        pcnt[3]--;
    }
    while (pcnt[5] > 0) {
        res += '5';
        pcnt[5]--;
    }
    while (pcnt[3] > 0 && pcnt[2] >= 2) {
        res += '4';
        pcnt[3]--;
        pcnt[2] -= 2;
