#include <map>
#include <vector>
#include <algorithm>
using namespace std;

map<int, vector<int>> primeFactors = {
    {2, {2}},
    {3, {3}},
    {4, {2, 2}},
    {5, {5}},
    {6, {2, 3}},
    {7, {7}},
    {8, {2, 2, 2}},
    {9, {3, 3}}
};

int main() {
    int n;
    string a;
    cin >> n >> a;

    map<int, int> totalExponents;
    for (char c : a) {
        int d = c - '0';
        if (d <= 1) continue;
        for (int p : primeFactors[d]) {
            totalExponents[p]++;
        }
    }

    vector<int> digits;
    while (totalExponents[7] > 0) {
        digits.push_back(7);
        totalExponents[7]--;
    }
    while (totalExponents[5] > 0) {
        digits.push_back(5);
        totalExponents[5]--;
    }
    while (totalExponents[3] > 0) {
        digits.push_back(3);
        totalExponents[3]--;
    }
    while (totalExponents[2] > 0) {
        digits.push_back(2);
        totalExponents[2]--;
    }

    for (int d : digits) {
        cout << d;
    }
    cout << endl;

    return 0;
